NavigationStack {
    ScrollView {
        VStack(alignment: .leading, spacing: theme.spacing.space4) {
            Text({{description}})
                .monarchTextStyle(.body)
                .foregroundStyle(theme.colors.textMuted)
            ViewThatFits(in: .horizontal) {
                HStack(spacing: theme.spacing.space2) {
                    periodPicker(fillsWidth: false)
                    Toggle({{arrange}}, isOn: $isEditing)
                        .toggleStyle(.monarchButton(.outline, size: .sm))
                }
                VStack(alignment: .trailing, spacing: theme.spacing.space2) {
                    periodPicker(fillsWidth: true)
                    Toggle({{arrange}}, isOn: $isEditing)
                        .toggleStyle(.monarchButton(.outline, size: .sm))
                }
            }
            LazyVGrid(
                columns: Array(
                    repeating: GridItem(.flexible(), spacing: theme.spacing.space3),
                    count: dynamicTypeSize.isAccessibilitySize ? 1 : 2
                ),
                spacing: theme.spacing.space3
            ) {
                MonarchStatCard({{kpis.0.label}}, value: {{kpis.0.value}}, change: MonarchMetricChange({{kpis.0.change.value}}, comparison: {{kpis.0.change.comparison}}, goodDirection: .{{kpis.0.change.goodDirection|raw}}))
                MonarchStatCard({{kpis.1.label}}, text: {{kpis.1.text}}, change: MonarchMetricChange({{kpis.1.change.value}}, comparison: {{kpis.1.change.comparison}}, goodDirection: .{{kpis.1.change.goodDirection|raw}}))
                MonarchStatCard({{kpis.2.label}}, value: {{kpis.2.value}}, change: MonarchMetricChange({{kpis.2.change.value}}, comparison: {{kpis.2.change.comparison}}))
                MonarchStatCard({{kpis.3.label}}, value: {{kpis.3.value}}, format: .{{kpis.3.format|raw}})
            }
            .accessibilityElement(children: .contain)
            .accessibilityLabel("Key figures")
            MonarchInsightStrip(
                "Insights",
                insights: [
                    MonarchInsight(
                        id: {{insight.id}},
                        title: {{insight.title}},
                        why: {{insight.why}},
                        tone: .{{insight.severity|raw}},
                        origin: .{{insight.origin|raw}},
                        actionTitle: {{insight.action}},
                        action: {}
                    )
                ]
            )
            MonarchDashboardGrid(
                HomeSection.allCases,
                layout: $layout,
                itemLabel: \.title,
                span: { $0.span },
                isEditing: isEditing,
                labels: MonarchDashboardGridLabels(label: "Dashboard sections"),
                content: { section in
                    switch section {
                    case .status:
                        MonarchWidget(section.title) {
                            LabeledContent({{status.0.label}}) {
                                MonarchStatusBadge(MonarchStatusDefinition({{status.0.state}}, tone: {{status.0.tone|tone}}, systemImage: "checkmark.circle"))
                            }
                            LabeledContent({{status.1.label}}) {
                                MonarchStatusBadge(MonarchStatusDefinition({{status.1.state}}, tone: {{status.1.tone|tone}}, systemImage: "exclamationmark.triangle"))
                            }
                            LabeledContent({{status.2.label}}) {
                                MonarchStatusBadge(MonarchStatusDefinition({{status.2.state}}, tone: {{status.2.tone|tone}}, systemImage: "checkmark.circle"))
                            }
                        }
                    case .attention:
                        MonarchWidget(section.title) {
                            LabeledContent({{attention.0.label}}) {
                                MonarchBadge({{attention.0.badge}}, tone: {{attention.0.tone|tone}})
                            }
                            LabeledContent({{attention.1.label}}) {
                                MonarchBadge({{attention.1.badge}}, tone: {{attention.1.tone|tone}})
                            }
                        }
                    case .queue:
                        MonarchWidget(section.title) {
                            LabeledContent({{queue.0.label}}) {
                                MonarchBadge({{queue.0.badge}}, tone: {{queue.0.tone|tone}})
                            }
                            LabeledContent({{queue.1.label}}) {
                                MonarchBadge({{queue.1.badge}}, tone: {{queue.1.tone|tone}})
                            }
                            LabeledContent({{queue.2.label}}) {
                                MonarchBadge({{queue.2.badge}}, tone: {{queue.2.tone|tone}})
                            }
                        }
                    case .trend:
                        MonarchWidget(section.title) {
                            MonarchBarChart(
                                {{trend.title}},
                                categories: [{{trend.data.0.day}}, {{trend.data.1.day}}, {{trend.data.2.day}}, {{trend.data.3.day}}, {{trend.data.4.day}}],
                                series: [
                                    MonarchBarChartSeries({{trend.series.0.key}}, label: {{trend.series.0.label}}, values: [{{trend.data.0.opened|double}}, {{trend.data.1.opened|double}}, {{trend.data.2.opened|double}}, {{trend.data.3.opened|double}}, {{trend.data.4.opened|double}}]),
                                    MonarchBarChartSeries({{trend.series.1.key}}, label: {{trend.series.1.label}}, values: [{{trend.data.0.solved|double}}, {{trend.data.1.solved|double}}, {{trend.data.2.solved|double}}, {{trend.data.3.solved|double}}, {{trend.data.4.solved|double}}]),
                                ],
                                description: {{trend.description}},
                                categoryTitle: {{trend.categoryLabel}}
                            )
                        }
                    case .workload:
                        MonarchWidget(section.title) {
                            MonarchLeaderboard(
                                [
                                    MonarchLeaderboardEntry({{workload.entries.0.name}}, value: {{workload.entries.0.value|double}}, id: {{workload.entries.0.id}}, secondary: {{workload.entries.0.secondary}}),
                                    MonarchLeaderboardEntry({{workload.entries.1.name}}, value: {{workload.entries.1.value|double}}, id: {{workload.entries.1.id}}, secondary: {{workload.entries.1.secondary}}),
                                    MonarchLeaderboardEntry({{workload.entries.2.name}}, value: {{workload.entries.2.value|double}}, id: {{workload.entries.2.id}}, secondary: {{workload.entries.2.secondary}}),
                                ],
                                label: section.title,
                                valueLabel: {{workload.valueLabel}},
                                sort: .descending,
                                isCompact: true
                            )
                        }
                    case .upcoming:
                        MonarchWidget(section.title) {
                            LabeledContent({{upcoming.0.label}}, value: {{upcoming.0.value}})
                            LabeledContent({{upcoming.1.label}}, value: {{upcoming.1.value}})
                        }
                    case .activity:
                        MonarchWidget(section.title) {
                            MonarchActivityTimeline(
                                [
                                    MonarchActivityTimelineEvent(
                                        id: {{activity.0.id}},
                                        actor: MonarchActivityTimelineActor({{activity.0.actor}}),
                                        verb: {{activity.0.verb}},
                                        object: {{activity.0.object}},
                                        time: {{activity.0.time|date}}
                                    ),
                                    MonarchActivityTimelineEvent(
                                        id: {{activity.1.id}},
                                        actor: MonarchActivityTimelineActor({{activity.1.actor}}),
                                        verb: {{activity.1.verb}},
                                        object: {{activity.1.object}},
                                        time: {{activity.1.time|date}}
                                    ),
                                ],
                                isGroupedByDay: false,
                                density: .compact,
                                now: now
                            )
                        }
                    }
                }
            )
            .labeledContentStyle(.monarch)
        }
        .padding(theme.spacing.space4)
    }
    .monarchCanvas()
    .navigationTitle({{title}})
    #if os(iOS)
    .navigationBarTitleDisplayMode(.inline)
    #endif
}
.frame(maxWidth: .infinity, minHeight: theme.spacing.space24 * 8)

examples.setupTemplate:
@Environment(\.monarchTheme) private var theme
@Environment(\.dynamicTypeSize) private var dynamicTypeSize
@State private var period = {{period}}
@State private var layout: [String] = []
@State private var isEditing = false
private let now = {{now|date}}

/// The sections of the home screen, in their default order.
enum HomeSection: String, CaseIterable, Identifiable {
    case status, attention, queue, trend, workload, upcoming, activity

    var id: String { rawValue }

    var title: String {
        switch self {
        case .status: "Status"
        case .attention: "Needs attention"
        case .queue: "My queue"
        case .trend: "Trend"
        case .workload: "Team load"
        case .upcoming: "Coming up"
        case .activity: "Recent activity"
        }
    }

    /// Columns on an iPad; every section is full width on a phone.
    var span: MonarchDashboardGridSpan {
        switch self {
        case .status: .full
        case .attention, .trend: .two
        default: .one
        }
    }
}

@ViewBuilder private func periodPicker(fillsWidth: Bool) -> some View {
    MonarchSegmentedControl(
        "Period",
        selection: $period,
        items: [
            MonarchSegmentedItem({{periods.0.label}}, value: {{periods.0.id}}),
            MonarchSegmentedItem({{periods.1.label}}, value: {{periods.1.id}}),
            MonarchSegmentedItem({{periods.2.label}}, value: {{periods.2.id}}),
            MonarchSegmentedItem({{periods.3.label}}, value: {{periods.3.id}}),
            MonarchSegmentedItem({{periods.4.label}}, value: {{periods.4.id}}),
        ],
        size: .sm,
        fillsWidth: fillsWidth
    )
}

